13	constexpr int32_t BUFFER_NUM = 2;
14	
15	template <typename T>
16	class KernelAddCustom {
17	public:
18	    __aicore__ inline KernelAddCustom() {}
19	
20	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z,
21	                                int64_t formerNum, int64_t formerLength,
22	                                int64_t tailLength, int64_t tileLength)
23	    {
24	        int64_t blockIdx = AscendC::GetBlockIdx();
25	
26	        if (blockIdx < formerNum) {
27	            this->blockLength = formerLength;
28	            int64_t offset = formerLength * blockIdx;
29	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
30	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
31	            zGm.SetGlobalBuffer((__gm__ T *)z + offset, formerLength);
32	        } else {
33	            this->blockLength = tailLength;
34	            int64_t tailIdx = blockIdx - formerNum;
35	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
36	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
37	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
38	            zGm.SetGlobalBuffer((__gm__ T *)z + offset, tailLength);
39	        }
40	
41	        this->tileLength = tileLength;
42	
43	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
44	        pipe.InitBuffer(inQueueY, BUFFER_NUM, tileLength * sizeof(T));
45	        pipe.InitBuffer(outQueueZ, BUFFER_NUM, tileLength * sizeof(T));
46	
47	        if constexpr (sizeof(T) == sizeof(half)) {
48	            pipe.InitBuffer(tmpBufX, tileLength * sizeof(float));
49	            pipe.InitBuffer(tmpBufY, tileLength * sizeof(float));
50	            pipe.InitBuffer(tmpBufZ, tileLength * sizeof(float));
51	        }
52	    }
53	
54	    __aicore__ inline void Process()
55	    {
56	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
57	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
58	
59	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
60	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
61	
62	        for (int64_t i = 0; i < tileNum - 1; ++i) {
63	            CopyIn(i, this->tileLength);
64	            Compute(i, this->tileLength);
65	            CopyOut(i, this->tileLength);
66	        }
67	        if (tileNum > 0) {
68	            CopyIn(tileNum - 1, alignedTailLen);
69	            Compute(tileNum - 1, alignedTailLen);
70	            CopyOut(tileNum - 1, alignedTailLen);
71	        }
72	    }
73	
74	private:
75	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
76	    {
77	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
78	        AscendC::LocalTensor<T> yLocal = inQueueY.AllocTensor<T>();
79	
80	        AscendC::DataCopyExtParams copyParamsX{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
81	        AscendC::DataCopyPadExtParams<T> padParamsX{false, 0, 0, 0};
82	        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParamsX, padParamsX);
83	
84	        AscendC::DataCopyExtParams copyParamsY{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
85	        AscendC::DataCopyPadExtParams<T> padParamsY{false, 0, 0, 0};
86	        AscendC::DataCopyPad(yLocal, yGm[progress * this->tileLength], copyParamsY, padParamsY);
87	
88	        inQueueX.EnQue(xLocal);
89	        inQueueY.EnQue(yLocal);
90	    }
91	
92	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
93	    {
94	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
95	        AscendC::LocalTensor<T> yLocal = inQueueY.DeQue<T>();
96	        AscendC::LocalTensor<T> zLocal = outQueueZ.AllocTensor<T>();
97	
98	        if constexpr (sizeof(T) == sizeof(float)) {
99	            AscendC::Add(zLocal, xLocal, yLocal, curTileLength);
100	        } else {
101	            AscendC::LocalTensor<float> xFp32 = tmpBufX.Get<float>();
102	            AscendC::LocalTensor<float> yFp32 = tmpBufY.Get<float>();
103	            AscendC::LocalTensor<float> zFp32 = tmpBufZ.Get<float>();
104	
105	            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
106	            AscendC::Cast(yFp32, yLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
107	            AscendC::Add(zFp32, xFp32, yFp32, curTileLength);
108	            AscendC::Cast(zLocal, zFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
109	        }
110	
111	        outQueueZ.EnQue<T>(zLocal);
112	        inQueueX.FreeTensor(xLocal);
113	        inQueueY.FreeTensor(yLocal);
114	    }
115	
116	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
117	    {
118	        AscendC::LocalTensor<T> zLocal = outQueueZ.DeQue<T>();
119	
120	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
121	        AscendC::DataCopyPad(zGm[progress * this->tileLength], zLocal, copyParams);
122	
123	        outQueueZ.FreeTensor(zLocal);
124	    }
125	
126	private:
127	    AscendC::TPipe pipe;
128	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
129	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueY;
130	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueZ;
131	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufX;
132	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufY;
133	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufZ;
134	    AscendC::GlobalTensor<T> xGm;
135	    AscendC::GlobalTensor<T> yGm;
136	    AscendC::GlobalTensor<T> zGm;
137	    int64_t blockLength;
138	    int64_t tileLength;
139	};
140	
141	extern "C" __global__ __aicore__ void add_custom(GM_ADDR x, GM_ADDR y, GM_ADDR z,
142	                                                  int64_t formerNum, int64_t formerLength,
143	                                                  int64_t tailLength, int64_t tileLength,
144	                                                  int64_t dtypeSize)
145	{
146	    if (dtypeSize == 2) {
147	        KernelAddCustom<half> op;
148	        op.Init(x, y, z, formerNum, formerLength, tailLength, tileLength);
149	        op.Process();
150	    } else {
151	        KernelAddCustom<float> op;
152	        op.Init(x, y, z, formerNum, formerLength, tailLength, tileLength);
153	        op.Process();
154	    }
155	}
