21	
22	constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
23	
24	namespace ascend_kernel {
25	
26	at::Tensor add_custom(const at::Tensor &x, const at::Tensor &y)
27	{
28	    // ---- 输入校验 ----
29	    TORCH_CHECK(x.scalar_type() == y.scalar_type(),
30	                "add_custom: x and y must have the same dtype, got ", x.scalar_type(), " and ", y.scalar_type());
31	    TORCH_CHECK(x.scalar_type() == at::kHalf || x.scalar_type() == at::kFloat,
32	                "add_custom: only float16 and float32 are supported, got ", x.scalar_type());
33	    TORCH_CHECK(x.is_contiguous() && y.is_contiguous(),
34	                "add_custom: inputs must be contiguous");
35	
36	    // ---- 处理广播：确保 x, y 形状一致 ----
37	    at::Tensor x_b = x;
38	    at::Tensor y_b = y;
39	    if (x.sizes() != y.sizes()) {
40	        x_b = x.broadcast_to(y.sizes());
41	        y_b = y.broadcast_to(x.sizes());
42	    }
43	    std::vector<int64_t> out_shape;
44	    if (x_b.numel() >= y_b.numel()) {
45	        out_shape = x_b.sizes().vec();
46	    } else {
47	        out_shape = y_b.sizes().vec();
48	    }
49	
50	    at::Tensor output = at::empty(out_shape, x.options());
51	
52	    int64_t totalLength = output.numel();
53	    if (totalLength == 0) {
54	        return output;
55	    }
56	
57	    int64_t dtypeSize = output.element_size();
58	
59	    // ---- 获取硬件参数 ----
60	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
61	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
62	    uint64_t ubSize;
63	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
64	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
65	
66	    // ---- Block 级 tiling (核间切分, Cache Line 对齐) ----
67	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
68	    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
69	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
70	
71	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
72	    int64_t formerNum = usedCoreNum - 1;
73	    int64_t formerLength = totalLengthCoreAlign;
74	    int64_t tailLength = totalLength - formerNum * formerLength;
75	
76	    // ---- UB 级 tiling (核内切分) ----
77	    // 双输入算子: float32 bufferCoefficient = 32, float16 bufferCoefficient = 24
78	    int64_t bufferCoefficient;
79	    if (dtypeSize == 4) {
80	        bufferCoefficient = 32;  // float32
81	    } else {
82	        bufferCoefficient = 24;  // float16
83	    }
84	    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
85	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
86	    if (dtypeSize == 0) { dtypeSize = 1; }
87	    int64_t alignElements = 32 / dtypeSize;
88	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
89	    if (tileLength <= 0) {
90	        tileLength = alignElements;
91	    }
92	
93	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
94	
95	    // EXEC_KERNEL_CMD 所有参数必须是左值
96	    int64_t leftFormerNum = formerNum;
97	    int64_t leftFormerLength = formerLength;
98	    int64_t leftTailLength = tailLength;
99	    int64_t leftTileLength = tileLength;
100	    int64_t leftDtypeSize = dtypeSize;
101	
102	    EXEC_KERNEL_CMD(add_custom, blockDim,
103	                    x_b, y_b, output,
104	                    leftFormerNum, leftFormerLength, leftTailLength, leftTileLength, leftDtypeSize);
105	
106	    return output;
107	}
108	
109	}  // namespace ascend_kernel
