 * See LICENSE in the root of the software repository for the full text of the License.
 */

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelAddcmul {
public:
    __aicore__ inline KernelAddcmul() {}

    __aicore__ inline void Init(GM_ADDR data, GM_ADDR x1, GM_ADDR x2, GM_ADDR value, GM_ADDR output,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            dataGm.SetGlobalBuffer((__gm__ T *)data + offset, formerLength);
            x1Gm.SetGlobalBuffer((__gm__ T *)x1 + offset, formerLength);
            x2Gm.SetGlobalBuffer((__gm__ T *)x2 + offset, formerLength);
            outGm.SetGlobalBuffer((__gm__ T *)output + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            dataGm.SetGlobalBuffer((__gm__ T *)data + offset, tailLength);
            x1Gm.SetGlobalBuffer((__gm__ T *)x1 + offset, tailLength);
            x2Gm.SetGlobalBuffer((__gm__ T *)x2 + offset, tailLength);
            outGm.SetGlobalBuffer((__gm__ T *)output + offset, tailLength);
        }

        // value is a single scalar element, load once into TBuf
        valueGm.SetGlobalBuffer((__gm__ T *)value, 1);

        this->tileLength = tileLength;

        pipe.InitBuffer(inQueueData, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(inQueueX1, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(inQueueX2, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(valueBuf, sizeof(T));
        pipe.InitBuffer(outQueue, BUFFER_NUM, tileLength * sizeof(T));

        if constexpr (sizeof(T) != sizeof(float)) {
            pipe.InitBuffer(tmpDataFp32, tileLength * sizeof(float));
            pipe.InitBuffer(tmpX1Fp32, tileLength * sizeof(float));
            pipe.InitBuffer(tmpX2Fp32, tileLength * sizeof(float));
            pipe.InitBuffer(tmpMulFp32, tileLength * sizeof(float));
            pipe.InitBuffer(tmpOutFp32, tileLength * sizeof(float));
            pipe.InitBuffer(tmpValueFp32, sizeof(float));
        }

        // Load the scalar value once from GM into TBuf
        AscendC::LocalTensor<T> valLocal = valueBuf.Get<T>();
        AscendC::DataCopyExtParams copyValParams{1, static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padValParams{false, 0, 0, 0};
        AscendC::DataCopyPad(valLocal, valueGm, copyValParams, padValParams);
        AscendC::PipeBarrier<AscendC::PIPE_MTE2>();
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            CopyIn(tileNum - 1, alignedTailLen);
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, alignedTailLen);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> dataLocal = inQueueData.AllocTensor<T>();
        AscendC::LocalTensor<T> x1Local = inQueueX1.AllocTensor<T>();
        AscendC::LocalTensor<T> x2Local = inQueueX2.AllocTensor<T>();

        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};

        AscendC::DataCopyPad(dataLocal, dataGm[progress * this->tileLength], copyParams, padParams);
        AscendC::DataCopyPad(x1Local, x1Gm[progress * this->tileLength], copyParams, padParams);
        AscendC::DataCopyPad(x2Local, x2Gm[progress * this->tileLength], copyParams, padParams);

        inQueueData.EnQue(dataLocal);
        inQueueX1.EnQue(x1Local);
        inQueueX2.EnQue(x2Local);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> dataLocal = inQueueData.DeQue<T>();
        AscendC::LocalTensor<T> x1Local = inQueueX1.DeQue<T>();
        AscendC::LocalTensor<T> x2Local = inQueueX2.DeQue<T>();
        AscendC::LocalTensor<T> outLocal = outQueue.AllocTensor<T>();

        if constexpr (sizeof(T) == sizeof(float)) {
            // FP32 direct path: out = data + x1 * x2 * value
            AscendC::LocalTensor<T> valueLocal = valueBuf.Get<T>();
            T scalarVal = valueLocal.GetValue(0);
            AscendC::Mul(outLocal, x1Local, x2Local, curTileLength);
            AscendC::Muls(outLocal, outLocal, scalarVal, curTileLength);
            AscendC::Add(outLocal, dataLocal, outLocal, curTileLength);
        } else {
            // FP16/BF16 path: Cast to float32, compute, Cast back
            AscendC::LocalTensor<float> dataFp32 = tmpDataFp32.Get<float>();
            AscendC::LocalTensor<float> x1Fp32 = tmpX1Fp32.Get<float>();
            AscendC::LocalTensor<float> x2Fp32 = tmpX2Fp32.Get<float>();
            AscendC::LocalTensor<float> mulFp32 = tmpMulFp32.Get<float>();
            AscendC::LocalTensor<float> outFp32 = tmpOutFp32.Get<float>();
            AscendC::LocalTensor<float> valueFp32 = tmpValueFp32.Get<float>();

            AscendC::LocalTensor<T> valueLocal = valueBuf.Get<T>();

            // Cast inputs to FP32
            AscendC::Cast(dataFp32, dataLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(x1Fp32, x1Local, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(x2Fp32, x2Local, AscendC::RoundMode::CAST_NONE, curTileLength);
            // Use Cast to convert single-element value from T to float
            AscendC::Cast(valueFp32, valueLocal, AscendC::RoundMode::CAST_NONE, 1);

            // Compute in FP32: out = data + x1 * x2 * value
            float scalarVal = valueFp32.GetValue(0);
            AscendC::Mul(mulFp32, x1Fp32, x2Fp32, curTileLength);
            AscendC::Muls(mulFp32, mulFp32, scalarVal, curTileLength);
            AscendC::Add(outFp32, dataFp32, mulFp32, curTileLength);

            // Cast back to T (half/bfloat16)
            AscendC::Cast(outLocal, outFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
        }

        outQueue.EnQue<T>(outLocal);
        inQueueData.FreeTensor(dataLocal);
        inQueueX1.FreeTensor(x1Local);
        inQueueX2.FreeTensor(x2Local);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> outLocal = outQueue.DeQue<T>();

        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(outGm[progress * this->tileLength], outLocal, copyParams);

        outQueue.FreeTensor(outLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueData;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX1;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX2;
    AscendC::TBuf<AscendC::TPosition::VECCALC> valueBuf;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpDataFp32;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpX1Fp32;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpX2Fp32;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpMulFp32;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpOutFp32;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpValueFp32;
    AscendC::GlobalTensor<T> dataGm;
    AscendC::GlobalTensor<T> x1Gm;
    AscendC::GlobalTensor<T> x2Gm;
    AscendC::GlobalTensor<T> valueGm;
    AscendC::GlobalTensor<T> outGm;
    int64_t blockLength;
    int64_t tileLength;
};

extern "C" __global__ __aicore__ void addcmul(GM_ADDR data, GM_ADDR x1, GM_ADDR x2, GM_ADDR value, GM_ADDR output,
                                               int64_t formerNum, int64_t formerLength,
                                               int64_t tailLength, int64_t tileLength,
                                               int64_t dtypeSize)
{
    if (dtypeSize == 2) {
        KernelAddcmul<half> op;
        op.Init(data, x1, x2, value, output, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else {
        KernelAddcmul<float> op;
        op.Init(data, x1, x2, value, output, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    }
}
