#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_addcmul.h"

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

namespace ascend_kernel {

at::Tensor addcmul(const at::Tensor &inputData, const at::Tensor &inputX1,
                   const at::Tensor &inputX2, const at::Tensor &value)
{
    // ---- 输入校验 ----
    TORCH_CHECK(inputData.scalar_type() == inputX1.scalar_type() &&
                inputData.scalar_type() == inputX2.scalar_type() &&
                inputData.scalar_type() == value.scalar_type(),
                "addcmul: all inputs must have the same dtype");
    TORCH_CHECK(inputData.scalar_type() == at::kHalf || inputData.scalar_type() == at::kFloat,
                "addcmul: only float16 and float32 are supported, got ", inputData.scalar_type());
    TORCH_CHECK(inputData.is_contiguous() && inputX1.is_contiguous() &&
                inputX2.is_contiguous() && value.is_contiguous(),
                "addcmul: all inputs must be contiguous");

    // ---- 创建输出 ----
    std::vector<int64_t> outShape = inputData.sizes().vec();
    at::Tensor output = at::empty(outShape, inputData.options());

    int64_t totalLength = output.numel();
    if (totalLength == 0) {
        return output;
    }

    int64_t dtypeSize = output.element_size();

    // ---- 获取硬件参数 ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block 级 tiling (核间切分, Cache Line 512B 对齐) ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

