    // 4-input (3 large + 1 scalar) + 1 output:
    //   float32: 3*2*sizeof(float) (VECIN) + 2*sizeof(float) (VECOUT) + 4 (value) = 24+8+4 = 36
    //   float16: 3*2*sizeof(half) (VECIN) + 2*sizeof(half) (VECOUT) + 5*sizeof(float) (fp32 bufs) + 2 (value)
    //          = 12+4+20+2 = 38, use 40
