    at::Tensor dataFlat = inputData.reshape(-1).contiguous();
    at::Tensor x1Flat = inputX1.reshape(-1).contiguous();
    at::Tensor x2Flat = inputX2.reshape(-1).contiguous();
    at::Tensor valueFlat = value.reshape(-1).contiguous();
    at::Tensor outFlat = output.reshape(-1).contiguous();

    // EXEC_KERNEL_CMD 所有参数必须是左值
    int64_t leftFormerNum = formerNum;
    int64_t leftFormerLength = formerLength;
    int64_t leftTailLength = tailLength;
    int64_t leftTileLength = tileLength;
    int64_t leftDtypeSize = dtypeSize;

    EXEC_KERNEL_CMD(addcmul, blockDim,
                    dataFlat, x1Flat, x2Flat, valueFlat, outFlat,
                    leftFormerNum, leftFormerLength, leftTailLength, leftTileLength, leftDtypeSize);

    return output;
}

